REPLACE INTO eval_opinion(opinion_id, review_id, department, rule_id, title, content, risk_level, sort_order, create_time) VALUES
(1, 0, '财务部', '', '南洋公司与八局西南公司（60%', '南洋公司与八局西南公司（60%:40%）组成内部联营体，以中建股份新加坡办事处名义投标，建议履约阶段明确项目管委会关键人员委派、重大事项决策及争议解决机制，做好权责利界面划分，尤其是资金、账务、税务分摊安排，避免内部合作争议。', 'medium', 1, NOW()),
(2, 0, '财务部', '', '建议删除保函格式中“没有义务调查索赔或指示的理由、', '建议删除保函格式中“没有义务调查索赔或指示的理由、情况或真实性”“自动延长180天（届满失效），除非责任到期前90天以书面形式通知将不延期”相关表述，增加预付款保函的减额条款。', 'medium', 2, NOW()),
(3, 0, '财务部', '', '建议将违约责任上限控制在合理范围（10%以下）', '建议将违约责任上限控制在合理范围（10%以下），并关注误期阶段性误期违约金设置的合理性，明确后续施工中追回进度后可退还进度违约金。', 'medium', 3, NOW()),
(4, 0, '法律事务部', '', '建议将支付预付款作为开工条件', '建议将支付预付款作为开工条件,补充约定承包商违约责任上限和承包商停工权、解约权，限制业主为交由其他承包商施工而任意解除合同的权利。此外，合同约定的误期违约金上限过高，建议降低至合同额的10%。', 'medium', 1, NOW()),
(5, 0, '法律事务部', '', '建议向业主澄清合同第30A 条所述Specialist', '建议向业主澄清合同第30A条所述SpecialistContractor的身份和合同内容。', 'medium', 2, NOW()),
(6, 0, '法律事务部', '', '合同第31 条约定', '合同第31条约定，收到解约证书后，承包商整改期仅有7天。解约后，承包人在现场的设备、仪器、临建、货物等物品均不得撤场，且业主对所有物品享有留置权。建议与业主协商延长整改期至14天，解约后承包人有权从现场运走除货物和承包商文件以外的所有其他物品。', 'medium', 3, NOW()),
(7, 0, '法律事务部', '', '建议增加预付款保函减额条款', '建议增加预付款保函减额条款，兑付保函需提交违约情形声明，并删除保函自动延期条款。', 'medium', 4, NOW()),
(8, 0, '法律事务部', '', '建议中标后细化实施阶段的内部联营协议', '建议中标后细化实施阶段的内部联营协议，做好内部联营分工安排，明确双方责任划分，落实重大事项协商决策机制，避免发生内部争议。', 'medium', 5, NOW()),
(9, 0, '海外部', '', '本项目尚未完成商务部备案', '本项目尚未完成商务部备案，请确保在投标前完成备案工作。', 'medium', 1, NOW()),
(10, 0, '海外部', '', '建议增加业主违约时承包商的停工权和解约权', '建议增加业主违约时承包商的停工权和解约权，以及承包商违约责任上限，制定业主不同意情况下的应对措施。', 'medium', 2, NOW()),
(11, 0, '海外部', '', '本项目同时设定了总工期和里程碑节点的误期罚款', '本项目同时设定了总工期和里程碑节点的误期罚款，罚款上限高（20%）。建议争取降低误期罚款上限以及当总工期追回情形下可退还阶段罚款，并补充说明工期风险防范措施。', 'medium', 3, NOW()),
(12, 0, '海外部', '', '据特殊条款第5.2 条', '据特殊条款第5.2条，承包商不能因地下市政设施和巨石等障碍物获得费用和工期补偿。考虑到本项目全部为地下工程，建议明确由业主承担地下物理条件和不可知障碍物风险，并在投标阶段审慎核实地质条件，高度关注地质风险。', 'medium', 4, NOW()),
(13, 0, '海外部', '', '据特殊条款第12.1 条', '据特殊条款第12.1条，业主延迟提供场地时，承包商仅能获得工期补偿。建议将业主移交场地和支付预付款作为开工前提条件，争取延迟移交场地时的费用索赔权。', 'medium', 5, NOW()),
(14, 0, '海外部', '', '据特殊条款第30A.1 条', '据特殊条款第30A.1条，承包商同意与业主、专业承包商（SpecialistContractor）签订转让协议，以接替业主在与专业承包商合同中的位置。请补充说明专业承包商的工作内容、履约情况以及与业主签署的合同情况，制定专业承包商管理措施，同时明确由业主承担专业承包商合同转让前的风险。', 'medium', 6, NOW()),
(15, 0, '海外部', '', '本项目采用固定总价模式', '本项目采用固定总价模式，业主负责设计。请说明业主提供文件的深度和准确性对投标报价的影响，以及成本风险防范措施。', 'medium', 7, NOW()),
(16, 0, '海外部', '', '本项目以股份公司新加坡办事处名义参与投标', '本项目以股份公司新加坡办事处名义参与投标，A标段和B标段兼投可兼中，体量（97.2万平米）和资源需求量大。请委派一名副总经理亲自组织和指挥投标和中标后履约，选派优秀管理人员组成项目团队，并补充说明各项资源保障措施，以及项目实施的重点难点和应对措施，确保风险防范措施落实到投标报价和技术方案中。请补充提供拟定的项目班子成员及其简历。请就上述会签意见进行澄清与回复。2024年8月24日', 'medium', 8, NOW()),
(17, 0, '财务部、法律事务部、金融与专项资产管理部', 'F-R1,F-R3,F-R6', 'IPC支付周期风险及现金流管理建议', '进度款支付周期为业主收到IPC证书后{天数}天，材料未明确具体天数，需进一步确认。预付款比例仅5%，保留金5%，对现金流管理要求高。建议争取优化付款条款（如缩短支付周期、提高预付款比例），测算投标期资金峰值需求。基于内部联合体权益比例60%:40%，应明确联营体各方垫资比例及利息分摊机制，并在合同中约定。', 'medium', 0, NOW()),
(18, 0, '财务部', 'R-A1', '内部联营体权责划分与协议签订建议', '中建南洋公司与中建八局西南公司（60%:40%）组成内部联营体，建议：①在正式投标前签订标前协议，明确双方在投标和履约阶段的具体分工情况。投标阶段材料显示双方不划分工作范围，但履约阶段需细化分工，避免后续争议。②履约阶段明确项目管委会关键人员委派、重大事项决策及争议解决机制。材料中朱春霞指出项目总监、商务经理、财务总监均为中建南洋委派，对中建八局西南公司的成本核算和利润分析存在风险，应通过协议确保关键岗位共派或建立联合决策机制。③做好权责利界面划分，尤其是资金、账务、税务分摊安排。苏发山提出联合体界面分工需详细明确，避免管理重叠和盲区。材料提及消费税退税、现金流策划等财务安排，需在协议中明确分摊方式。以上建议基于《境外项目评审管理办法》第4章+附件1，旨在防范内部合作风险。', 'medium', 0, NOW()),
(19, 0, '财务部、法律事务部', 'R-B1,R-B2,R-B4,R-B5', '保函自动延期条款风险及建议修改', '履约保函格式中若包含“没有义务调查索赔理由、自动延长、权益可转让”等表述，将导致我方面临保函被无限期延长、索赔审查缺失及权益被转让等风险。根据FIDIC红皮书/黄皮书第4.2条，履约担保应在缺陷责任期前持续有效。本项目保修期12个月，A标段工期48个月，缺陷责任期应不晚于2029年第四季度。建议：删除保函中“自动延长”相关表述，明确保函具体失效日期；删除“没有义务调查索赔或指示的理由、情况或真实性”条款；删除保函权益可转让给第三方的条款；要求保函有效期明确覆盖至缺陷责任期结束（例如2029年12月31日）。材料中明确履约保函比例为5%，合同金额A+B标段46.67亿新元，保函金额约2.33亿新元，风险敞口巨大。', 'medium', 0, NOW()),
(20, 0, '财务部、海外部、法律事务部', 'R-D2,R-G1', '误期违约金上限20%过高，建议降至合同额10%', '合同约定的误期违约金上限为合同额的20%，高于FIDIC红皮书/黄皮书第8.7条通常标准的10%。建议在后续谈判中将上限降低至合同额的10%，以控制潜在财务风险。同时，材料未明确误期罚款日费率及计价基数，需进一步确认并在合同中明确合理数值，避免未来争议。', 'medium', 0, NOW()),
(21, 0, '财务部', 'R-H10', '成本控制风险：成本测算尚未完成，材料采购依赖进口', '成本测算尚未完成，存在报价不准确风险。项目预期利润8%，风险费2%，但材料设备采购依赖进口，需缴纳9%消费税，成本测算假设可全额退税，实际退税率不确定，若供应链波动或退税不充分可能导致成本超支。建议做好项目成本策划，提前锁定分供商成本，调研进口材料消费税退税情况，并在投标报价中预留风险准备金。材料未明确成本测算是否已最终定稿，需进一步确认。', 'medium', 0, NOW()),
(22, 0, '法律事务部', 'R-B3', '保函索赔条件需增加违约情形声明条款', '项目材料明确履约保函比例为5%（附件7策划方案表），但未提供保函格式文本，也未说明业主兑付保函时需提交何种证明材料。根据境外项目评审管理办法附件1第R-B3条（FIDIC红皮书/黄皮书第4.2条），保函索赔条件应要求业主提供违约证明。为防范业主单方无条件兑付保函的风险，建议在所有保函格式中增加业主兑付保函时需提交违约情形声明的条款，明确业主需出具书面声明详细说明承包商违约事实及依据，并附相关证据。该条款应作为保函附件或直接嵌入保函正文。材料未明确当前保函格式是否包含此要求，需在后续投标阶段落实。', 'medium', 0, NOW()),
(23, 0, '法律事务部、海外部、科技与设计管理部', 'R-E1', '业主设计+固定总价模式下设计深度不足的价格风险', '本项目由业主负责设计，计价方式为固定总价。法律角度：材料中中建八局评审记录提及专用条件第5条应明确业主提供的资料错误/地下管线风险由有经验承包商无法预计的应由业主承担，建议在合同中明确设计责任由业主承担，承包商仅对施工符合设计图纸和技术规范负责；如因业主设计缺陷导致工期延误或成本增加，承包商有权获得工期延长和费用补偿。商务角度：材料显示项目为固定总价，但业主要求填报主材可调差条件报价（A标段35.54亿新元，B标段11.26亿新元），建议充分评估业主提供图纸和资料的准确性对投标报价的影响，防范价格风险，并争取成本变动时的调价机制。技术角度：材料未明确技术报审计划，建议提前制定技术报审计划，确保设计变更和优化建议得到及时审批。', 'medium', 0, NOW()),
(24, 0, '法律事务部、海外部', 'R-G2,R-G4,R-G7,R-G8', '承包商停工权/解约权缺失风险及应对建议', '合同未约定业主付款违约时承包商的停工权及业主违约时的解约权（见评审记录第9、13条）。该缺失将导致业主长期拖欠工程款或发生其他重大违约时，我方无法合法暂停施工或终止合同，可能被迫持续投入资源，现金流风险和履约风险显著增大。建议：1. 向业主明确要求增加FIDIC第16条对应的停工权和解约权条款，条件应合理，如业主拖欠付款超过约定天数（如28天）即触发停工权，业主违约持续规定天数（如56天）即触发解约权，并明确停工期间费用补偿及解约后结算索赔路径。2. 若业主拒绝，则应制定应对预案：（a）加强过程付款催收与预警机制，设置专人跟踪付款进度，提前沟通；（b）评估法律救济途径，如新加坡法院的付款命令或仲裁；（c）在投标报价中考虑无停工权下的资金成本风险，提高风险费或现金流缓冲。上述条款的缺失属于重大合同风险，需在投标阶段务必争取解决。', 'medium', 0, NOW()),
(25, 0, '金融与专项资产管理部、法律事务部', 'R-B6', '保函权益转让条款风险及应对建议', '预付款保函和履约保函中的权益转让条款存在风险。材料未明确保函中是否包含权益可转让给第三方的条款，需进一步确认。根据FIDIC红皮书/黄皮书第1.3条及第4.2条，保函权益转让应经承包商同意。建议在投标阶段与业主沟通，争取删除保函转让条款，并明确保函的具体失效日期，防止保函被转让后带来的不可控风险。预付款比例为5%，履约保函比例为5%，保函金额较大，风险需重视。', 'medium', 0, NOW()),
(26, 0, '海外部', 'R-D1,R-D3,R-D4,R-G5,R-I2', '合并合同工期与风险条款评审意见', '合同工期与误期罚款条款存在多重叠加风险，且场地移交和地下条件条款对承包商不利。建议：1. 明确里程碑与总工期罚款不重叠或设置扣减机制，总工期追回时退还已扣罚款；各标段误期罚款计价基数应以其合同金额（A段35.88亿新元，B段11.32亿新元）为准，争取误期损害赔偿为唯一赔偿责任，限制第三方成本赔偿上限，并澄清日费率。2. 将业主移交场地和支付5%预付款作为开工前提条件，争取费用索赔权。3. 要求业主书面承诺承担地下不可预见物质条件风险（FIDIC第4.12条），组建地质专家独立复核地勘报告，核查保险条款（FIDIC第18条）是否覆盖地下障碍物风险并确保免赔额合理。', 'medium', 0, NOW()),
(27, 0, '海外部', 'R-E2,R-E3', '设计顾问协调与设计深度风险', '本项目设计顾问公司多达3家（SURBANA JURONG、ARUP、MOTT MACDONALD），设计协调难度大，且设计深度未明确，固定总价报价风险高。建议：1. 根据FIDIC黄皮书第5条，明确各设计顾问职责分工与接口，定期组织协调会议，建立沟通机制，并配备有经验的设计管理团队。2. 投标阶段详细审查设计图纸，提出价值工程优化方案，与业主及时澄清；报价中落实法律意见书意见二，充分考虑设计不确定性，预留不可预见费5,315.04万新加坡元（占总价1.48%），并锁定主要材料及设备成本。3. 评估专项审批周期对工期的影响，确保里程碑节点可控。', 'medium', 0, NOW()),
(28, 0, '海外部', 'R-G6', '甲指分包终止费用未明确，需在合同中约定由业主承担', '材料中显示业主指定分包及暂定项目金额为4,076.80万新加坡元，占投标总价1.14%，但未明确甲指分包合同终止后的费用承担规则。根据FIDIC红皮书/黄皮书第5条（分包），建议在合同谈判中明确：因甲指分包或业主原因导致分包合同终止时，由业主承担替换甲指分包所产生的全部费用，包括重新招标、动员、价格差异等成本。同时，应提前调研业主拟定的甲指分包工作内容和意向承包商，评估其资质和能力，避免因分包商履约不力导致我方连带风险。材料未提及甲指分包终止费用条款，需在后续合同审查中重点关注并补充相应保护性条款。', 'medium', 0, NOW()),
(29, 0, '海外部', 'R-H1', '商务部备案情况需进一步确认', '本项目材料未明确是否已按《对外承包工程项目备案和立项管理办法》完成商务部备案。境外工程承包项目应在投标前完成备案，若未完成则存在合规风险。建议评审单位要求项目公司补充备案证明或说明备案进度；如已备案，需提供备案编号；如未完成，应在正式投标前完成备案工作。', 'medium', 0, NOW()),
(30, 0, '海外部', 'R-H2', '管理团队配置风险：需明确项目指挥及班子人选', '该项目体量巨大（投标金额46.67亿新元），且由中建南洋公司与中建八局西南公司组成内部联合体（权益比例60%:40%），管理团队配置是履约关键。目前材料未明确项目总指挥人选及班子成员，存在管理统筹风险。依据《境外项目评审管理办法》第4章，请牵头单位中建南洋公司委派一名副总经理作为项目总指挥，亲自组织投标和后期实施，并提供拟选派项目班子成员及其简历。同时，请中建南洋公司与中建八局西南公司在ECI阶段即作为重点项目监管并提供必要支持，并书面说明合作机制（如决策流程、沟通协调方式）及费用承担原则（包括管理费、开办费等分摊方式），避免后续合作争议。', 'medium', 0, NOW()),
(31, 0, '海外部', 'R-H6', '分包招采计划不明确，需制定详细方案防范风险', '项目材料显示，投标阶段已与主材供应商和几家劳务分包商进行询价，但未提供系统的分包招采计划及工作界面划分方案。依据《境外项目评审管理办法》第4章，建议补充潜在分包资源的调研情况，明确各工作包责任边界，制定分包招采时间表、管理和协调方案，避免因招采滞后或界面不清导致成本和工期风险。此外，投标价格汇总表中列明指定分包及暂定项目4076.80万新加坡元（占总价1.14%），应在合同中明确约定：若招标后工作包金额超过暂定金额，总包商管理费不应调减，以保障我方利益。材料未明确暂定金额的调整机制，需进一步确认并写入合同。', 'medium', 0, NOW()),
(32, 0, '海外部、科技与设计管理部', 'R-H7', '项目实施重难点：巨量体、严标准、高罚款，需总部专项监管', '项目体量巨大（建筑面积97.2万平方米，拟投标金额46.67亿新元），工期紧张（A标48个月、B标54个月），且设置多达30余个里程碑节点，误期罚款每延误一天0.19-18.48万新元，上限高达合同额20%，远超常规管控指标。同时，项目引用新加坡标准、欧标、美标、英标等多套标准体系，材料设备选型及报价需逐项澄清。联合体分工界面需详细明确，避免管理重叠与盲区。劳动力、设备材料属地资源受限，且业主独立运营劳工营费用高昂（A标2400床位、B标1400床位，约500新币/月/床）。上述重难点若疏于防范，将直接导致工期、成本失控。请中建南洋公司（牵头单位）总部在投标报价阶段即作为重点项目监管，组织系统内外专家对投标方案进行充分论证，落实针对性防范措施：一是针对标准体系编制对照清单，提前与业主澄清；二是联合体协议明确资源配置、成本核算及关键岗位人员权责；三是现金流策划需充分考虑付款周期（35天）及9%消费税退税风险；四是工期罚款风险需在报价中合理计提风险费。同时，总部应建立专项监管机制，全过程跟踪项目实施，确保风险可控。', 'medium', 0, NOW()),
(33, 0, '海外部、科技与设计管理部', 'R-H8', '多标段兼投兼中资源匹配与冲突风险', '本项目分2个标段（A标段合同额35.88亿新元，工期48个月；B标段合同额11.32亿新元，工期54个月）且允许兼投兼中，拟定投标金额合计46.67亿新元。项目体量大，需大量资源投入，对资源组织能力要求高。请评估我方资源（人员、机械、资金等）能否同时支撑两个标段实施，防范标段间资源冲突风险。若存在同一区域其他在施项目，须一并说明资源统筹安排方案。材料未明确说明同一区域其他在施项目情况，需进一步确认。', 'medium', 0, NOW()),
(34, 0, '海外部、法律事务部', 'R-J4', '业主双重身份风险：需明确政府机构与业主角色界定', '业主樟宜机场集团为新加坡政府全资子公司，同时拥有政府机构和业主双重身份。合同采用《2020年公共部门建筑工程标准合同条件》（第八版），其关键条款可能约定业主作为政府机构时，承包商无权因政府行为（如监管调整、政策变更）而索赔工期或成本。当前材料未明确业主双重身份下的权力界限及承包商索赔权利，存在因身份模糊导致履约争议和索赔受阻的风险。建议在投标前或合同谈判中，要求业主明确其作为政府机构与业主的具体身份界定，并书面确认承包商在何种情况下可对政府行为导致的延误或成本增加提出索赔，避免履约中丧失合法索赔权利。', 'medium', 0, NOW()),
(35, 0, '重点', '', '项目资金风险', '项目资金风险请密切关注业主资金落实情况，在投标偏离表中增加要求业主提供资金安排合理证明以及工程量减少时业主应支付承包商损失的成本和利润的条款，将业主提供资金已落实的证明文件作为签约条件，制定业主支付违约的应对措施，防范项目回款风险。此外，不得为项目融资提供任何形式的母公司担保、增信措施以及承担还款责任。', 'medium', 1, NOW()),
(36, 0, '重点', '', '现金流风险', '现金流风险请在投标偏离表中明确“税务保证金和保留金总额不得超过合同金额的10%”和“保留金可以用保函替代”，如业主坚持税务保证金+保留金比例为15%，则落实放弃签约的承诺，并做好全周期现金流测算，提前落实垫付资金来源，严格履行相应的审批决策程序，避免计划外垫资。', 'medium', 2, NOW()),
(37, 0, '重点', '', '工期风险', '工期风险请在投标偏离表中约定各阶段误期罚款以标段合同金额为计算基数，制定工期风险防范措施。', 'medium', 3, NOW()),
(38, 0, '重点', '', '价格风险', '价格风险请充分评估业主指定供应商提供相关服务的能力,做好工期和成本责任划分，并在投标报价中充分考虑业主指定供应商后期涨价的风险,争取成本变动时价格可调,防范项目成本风险。', 'medium', 4, NOW()),
(39, 0, '重点', '', '设计风险', '设计风险本项目承包商负责设计,设计标准为沙特标准。请提前落实设计资源和有经验的设计管理团队,制定设计风险防范措施。', 'medium', 5, NOW()),
(40, 0, '重点', '', '保函风险', '保函风险请密切关注保函可转让和自动延期条款，中标后落实投标偏离表中提出的“合同转让（保函转让随合同转让而转让）应事先获得承包商的同意，但承包商不得无故拖延该同意”以及明确保函具体失效日期。', 'medium', 6, NOW()),
(41, 0, '重点', '', '限制承包商违约责任范围', '限制承包商违约责任范围请在投标偏离表中确认承包商违约责任上限为合同金额，并限定违约责任范围，避免责任范围过度扩大，提前制定业主不同意情况下的应对措施。', 'medium', 7, NOW()),
(42, 0, '重点', '', '母公司担保', '母公司担保请在投标偏离表中明确“承包商不会提供母公司担保”，并在中标后确保落实。', 'medium', 8, NOW()),
(43, 0, '重点', '', '内部合作模式', '内部合作模式请中建国际切实履行履约主体责任，与内部单位做好具体管理界面划分,落实重大事项管控机制,严控股份公司承接项目风险，并做好并表判断，完善过程分红机制和业绩考核比例，中标后签署实施阶段联营协议。', 'medium', 9, NOW()),
(44, 0, '重点', '', '外部合作风险', '外部合作风险请适时签订实施阶段合作协议，明确外部联合体的合作模式、决策机制和工作范围，在合作协议中落实过程分红机制，有效保障我方权益。此外，请确保我方无需向外部联合体合作方提供任何形式的担保、无需代合作方开具保函。', 'medium', 10, NOW()),
(45, 0, '重点', '', '规划以自身名义承接沙特地区项目', '规划以自身名义承接沙特地区项目请中建国际在今后的投标活动中谨慎论证以股份公司名义承接项目的必要性,研判以自身名义参与项目投标活动的可行性,更加关注自身在该地区的资质获取和业绩积累,尝试通过联营、分包等方式加快属地公司实体化经营的进程,尽量减少股份公司境外投标、履约活动的风险。', 'medium', 11, NOW()),
(46, 0, '财务部', '', '内外部联营风险', '内外部联营风险。中建占比33.33%，与ESEC（33.34%）、HACS（33.33%）组成外部联营体，建议明确外部联营体在决策权、利润分配、风险分担等方面权责，限制单方面决策权，避免决策僵局风险。中建中东、中建国际、中建三局权益分配接近均等（33.4%:33.3%:33.3%），可能因利益分配或管理分歧影响项目执行效率，建议明确分工界面和成本分摊机制。', 'medium', 1, NOW()),
(47, 0, '财务部', '', '现金流风险', '现金流风险。进度款支付周期为业主收到IPC证书后60天，且最小付款金额1000万里亚尔，保函金比例10%，材料设备装运后仅支付70%，对现金流管理要求高，建议争取优化付款条款。同时，两阶段投标间隔5个月，前期垫资压力未量化，建议测算投标期资金峰值需求，明确联营体各方垫资比例及利息分摊机制。中国建筑股份有限公司', 'medium', 2, NOW()),
(48, 0, '财务部', '', '成本控制风险', '成本控制风险。成本测算尚未完成，存在报价不准确风险。材料设备本地采购依赖性强，若供应链波动可能导致成本超支，建议做好项目成本策划，提前锁定分供商成本，并在投标报价中预留风险准备金。', 'medium', 3, NOW()),
(49, 0, '财务部', '', '保函风险', '保函风险。项目分5个标段独立工期，建议争取分标段分别开具保函，分阶段释放保函金额（按关键里程碑逐步减少保函比例），设定保函金额上限和有效期，避免敞口风险。建议争取删除不利条款（如自动续期、无条件转让），增加如违约声明等索赔条件。', 'medium', 4, NOW()),
(50, 0, '金融与专项资产管理部', '', '本项目资金来源为业主自筹', '本项目资金来源为业主自筹，业主为奇迪亚投资公司，由沙特公共投资基金（PIF）全资控股。建议密切关注业主资金落实情况和项目融资进展，防范项目回款风险。进一步在投标文件中明确我方不负责项目融资，不为项目融资提供任何形式的母公司担保或增信措施。', 'medium', 1, NOW()),
(51, 0, '金融与专项资产管理部', '', '我方需向业主提交预付款保函和履约保函', '我方需向业主提交预付款保函和履约保函，建议主张单位进一步落实保函开具要求，充分评估公司财务金融资源能否支撑项目保函金额，严格履行保函开具程序，确保保函开具合法合规。', 'medium', 2, NOW()),
(52, 0, '金融与专项资产管理部', '', '建议主张单位做好项目现金流测算', '建议主张单位做好项目现金流测算，在合同中约定业主未按期付款的违约责任，严防出现过程垫资，做好流动性风险防范。', 'medium', 3, NOW()),
(53, 0, '法律事务部', '', '据相关沟通该情况', '据相关沟通该情况，本项目中建内部合作方式尚未明确，建议相应修改合作协议。同时，请各参与单位坚持利益共享、风险共担原则，加强内部合作，并严格遵守修改后的合作协议。', 'medium', 1, NOW()),
(54, 0, '法律事务部', '', '建议明确项目设计责任由业主承担', '建议明确项目设计责任由业主承担，并协商约定不可预见物质条件下的承包商索赔权。', 'medium', 2, NOW()),
(55, 0, '法律事务部', '', 'IPC 最低金额为1000 万元里亚尔', 'IPC最低金额为1000万元里亚尔，该标准较高建议向业主争取降低，过程中合理规划工作进度，及时确权，避免垫资。同时，建议增加有关业主披露资金安排的条款。', 'medium', 3, NOW()),
(56, 0, '法律事务部', '', '建议向业主协商修改保函格式', '建议向业主协商修改保函格式，各保函不可自动续期、兑付时需提供违约情形声明，预付款保函额度随抵扣递减。', 'medium', 4, NOW()),
(57, 0, '法律事务部', '', '建议落实法律意见书中有关合同转让、业主任意解除权、', '建议落实法律意见书中有关合同转让、业主任意解除权、承包商停工与解除权等意见。', 'medium', 5, NOW()),
(58, 0, '海外部', '', '本项目尚未完成商务部门备案', '本项目尚未完成商务部门备案，请确保在正式投标前完成备案工作。', 'medium', 1, NOW()),
(59, 0, '海外部', '', '业主为沙特公共投资基金PIF 的全资子公司', '业主为沙特公共投资基金PIF的全资子公司，考虑到PIF为大量沙特项目提供资金，请密切关注PIF和业主财务状况，提前制定业主支付违约的应对预案。', 'medium', 2, NOW()),
(60, 0, '海外部', '', '本项目由业主负责设计', '本项目由业主负责设计，计价方式为固定总价，建议充分评估业主提供图纸和资料的准确性对投标报价的影响，防范价格风险，并争取成本变动时的调价机制。此外，请补充说明拟采取的外立面、内装以及景观技术报审计划和管理团队，防范装饰装修履约风险。', 'medium', 3, NOW()),
(61, 0, '海外部', '', '本项目包括5 个单位工程（Section）', '本项目包括5个单位工程（Section），分别设定完工日期，误期损害违约金均为0.006%合同额/天，且发生工期延误时，承包商应赔偿业主在第三方协议下发生的成本。建议明确误期损害违约金是承包商对其拖延完工的唯一赔偿责任，以及各单位工程误期罚款的计价基数为各单位工程合同额和总工期追回时退还过程罚款，并补充说明拟采取的工期风险防范措施。', 'medium', 4, NOW()),
(62, 0, '海外部', '', '据特殊条款16 条', '据特殊条款16条，业主未付款金额至少达到合同额50%时承包商才有权行使停工权和解约权。请确保删除或降低承包商行使相关权利时业主未付款金额限制，制定业主不同意情况下的应对措施。', 'medium', 5, NOW()),
(63, 0, '海外部', '', '建议缩短进度款支付周期（监理审核周期28 天', '建议缩短进度款支付周期（监理审核周期28天，业主支付周期60天）和删除最小付款金额限制（1000万里亚尔），做好全周期项目现金流策划，避免过程垫资，并补充提供项目策划方案表。', 'medium', 6, NOW()),
(64, 0, '海外部', '', '建议争取承包商在业主延迟提供场地、当局原因造成延误', '建议争取承包商在业主延迟提供场地、当局原因造成延误和不抗力情形下的费用索赔权。', 'medium', 7, NOW()),
(65, 0, '海外部', '', '据通用条款5.1.5 条', '据通用条款5.1.5条，甲指分包合同被终止后，承包商承担替换甲指分包的费用。建议明确因甲指分包或业主原因造成甲指分包合同终止时，由业主承担替换甲指分包的费用，并提前调研业主拟定甲指分包的工作内容和意向承包商。', 'medium', 8, NOW()),
(66, 0, '海外部', '', '请补充说明外部联合体合作模式、决策机制和各方分工', '请补充说明外部联合体合作模式、决策机制和各方分工，并确保我方无需向合作方提供任何形式的担保、无需代合作方开具保函。', 'medium', 9, NOW()),
(67, 0, '海外部', '', '据相关沟通情况', '据相关沟通情况，中建系统内部的合作方式多次发生变化。请中东公司、中建国际和三局尽快确认最终合作方式和联营比例，补充说明投标和实施阶段各方分工和资源投入情况，并按照《中建股份加强海外业务内部高效协同实施意见》要求签署标前合作协议，在中标后进一步细化实施阶段的联营协议，避免合作争议。', 'medium', 10, NOW()),
(68, 0, '海外部', '', '本项目造型独特', '本项目造型独特，设计灵感来自飞船，整体结构由5个支撑腿支撑，极具未来感，加工和安装精度高，且位于悬崖边，环保、安全要求高，工期较紧张（1643天）。请充分分析项目实施面临的重难点，落实各项风险防范措施，组织系统内外专家，做好投标方案的评审论证，并由牵头单位委派一名副总经理亲自组织投标和中标后实施，严控股份公司名义承接项目风险。', 'medium', 11, NOW()),
(69, 0, '海外部', '', '据投标情况说明和履约承诺函', '据投标情况说明和履约承诺函，中东公司和中建国际拟委派的班子成员与已中标的沙特德拉伊耶二期歌剧院街区项目完全相同，请结合中建各参与单位在沙特管理人员情况，做好中建方管理团队组建，提供拟选派的项目班子成员简历。', 'medium', 12, NOW()),
(70, 0, '科技与设计管理部', '', '本项目工期1643 天', '本项目工期1643天，请在投标阶段充分考虑当地习俗和季节影响，在工期推演时须充分考虑,高度重视工期风险。', 'medium', 1, NOW()),
(71, 0, '科技与设计管理部', '', '对于塔吊选型与布置、钢结构安装工艺选择等措施类技术', '对于塔吊选型与布置、钢结构安装工艺选择等措施类技术方案，请充分做好方案比选，为商务验算提供详实支撑，做好标前策划。', 'medium', 2, NOW()),
(72, 0, '科技与设计管理部', '', '请对当地资源进行摸排', '请对当地资源进行摸排，例如施工机械、建筑材料的市场供应情况，技术方案要充分结合当地的实际情况，既能较准确锁定投标阶段成本，也可以确保后期的可实施性。请就上述会签意见进行澄清与回复。2025年5月19日', 'medium', 3, NOW()),
(73, 0, '财务部、法律事务部、金融与专项资产管理部', 'F-R1,F-R3,F-R6', 'IPC支付周期过长及现金流风险', '进度款支付周期为业主收到IPC证书后{天数}天，材料未明确具体天数，需进一步确认。该支付周期对现金流管理要求高，建议在投标阶段争取优化付款条款，缩短支付周期或增加里程碑付款。同时应测算投标期资金峰值需求，并依据内部联营体权益比例（中建中东33.4%、中建国际33.3%、中建三局33.3%）及外部联营体牵头方ESEC（33.34%），明确联营体各方垫资比例及利息分摊机制，以防范现金流风险。', 'medium', 0, NOW()),
(74, 0, '财务部、法律事务部', 'F-R2', '最小付款金额1000万里亚尔过高，建议争取降低并防范垫资风险', '合同条件SCHEDULE 1 PARTICULAR CONDITIONS-14.5.2规定最小付款金额为1000万里亚尔，标准较高。建议在投标阶段向业主争取降低该金额，例如争取降至500万里亚尔或以下，以减少单次付款门槛。若无法调整，施工过程中应合理规划工作进度，将各期完成的工程量尽量累积到超过1000万里亚尔后再申请付款，避免因未达到最小付款金额而无法及时确权收款。同时，需密切关注进度款申请与支付流程，确保每期申请金额达标，避免因付款延迟导致垫资。材料中进度款支付周期为业主在收到IPC证书后60天内付款，垫资风险需通过优化进度和确权节奏加以控制。', 'medium', 0, NOW()),
(75, 0, '财务部、法律事务部', 'R-A1,R-A2,R-A4', '内部联营体权责划分不清晰，需签订标前协议并明确分工机制', '中建中东（33.4%）、中建国际（33.3%）与中建三局（33.3%）组成内部联营体，建议：①在正式投标前签订标前协议，明确双方在投标和履约阶段的具体分工情况；②履约阶段明确项目管委会关键人员委派、重大事项决策及争议解决机制；③做好权责利界面划分，尤其是资金、账务、税务分摊安排，避免内部合作争议。材料显示内部标前联合体协议为“待签”状态，需尽快完成签署并细化上述内容。', 'medium', 0, NOW()),
(76, 0, '财务部、法律事务部', 'R-B1,R-B2,R-B4,R-B5', '保函自动延期条款风险及建议', '保函格式中若含有''没有义务调查索赔或指示的理由、情况或真实性''''自动延长''等表述，将导致保函有效期不确定，承包商面临保函被无限期索赔且担保行无义务核实索赔真实性的风险。保函权益可转让给第三方的条款进一步增加我方责任，可能将保函转让给资信不明的主体。建议删除上述相关表述，明确保函具体失效日期，确保保函有效期与缺陷责任期截止日一致。本项目中，招标文件Schedule 23 Performance Bond及Schedule 24 Retention Bond的具体条款未在材料中提供，需在后续合同审核中重点关注并争取修改，以符合FIDIC红皮书/黄皮书第4.2条关于履约担保应在缺陷责任期前持续有效的要求，避免自动延期导致保函脱离我方控制。', 'medium', 0, NOW()),
(77, 0, '财务部、法律事务部', 'R-C1,R-C2', '母公司担保评估与替代方案（修正版）', '①财务角度：材料未明确母公司担保的具体金额及对资产负债率和担保额度占用的影响，需进一步评估并严格履行担保审批决策程序。建议优先由项目责任主体（子企业层级）提供担保，避免股份公司直接出具；若确需股份公司出具，需明确担保格式并向业主澄清，明确如后续格式不符无法出具时的法律责任。②法律角度：投标文件注明“提供母公司担保和担保人名称”的法律性质需澄清，材料未明确相关法律效果；同时需明确若决策同意出具担保但因格式不符无法出具时的法律责任。③替代方案：材料未提及中建国际提供母公司担保或中建八局提供增信的可能性，也未说明向业主提交替代担保方案的具体内容，需进一步研究可行性。', 'medium', 0, NOW()),
(78, 0, '财务部、海外部、法律事务部', 'R-D2,R-G1', '误期违约金上限过高风险', '合同约定的误期违约金上限比例在材料中未明确，需进一步确认。鉴于FIDIC红皮书/黄皮书第8.7条通常限定误期损害赔偿费上限为合同额的10%，若实际约定超过此标准，建议在投标阶段与业主协商降低至合同额的10%。同时，误期罚款日费率、计价基数等关键参数亦未明确，应一并在后续谈判中确认，确保整体条款合理可控。', 'medium', 0, NOW()),
(79, 0, '财务部', 'R-H10', '成本控制风险（新增）', '成本测算尚在推进，存在报价不准确风险。材料设备采购依赖属地资源，若供应链波动可能导致成本超支。建议加快完成成本测算，提前锁定分供商成本，并在投标报价中预留风险准备金。', 'medium', 0, NOW()),
(80, 0, '金融与专项资产管理部', 'F-R5,F-R4', '业主资金来源为PIF自有资金，需关注集中支付能力及合同保护', '业主奇迪亚投资公司（QIC）为沙特公共投资基金（PIF）全资子公司，资金来源为业主自有资金且已落实。尽管PIF管理资产规模超7000亿美元，资信可靠，但建议密切关注其未来集中支付能力，持续跟踪业主及合作方资信变化。请提供业主资金已落实的证明文件（如银行流水、审计报告等），并在合同中增加业主应提供资金安排合理证明的条款，以及工程量减少时业主应赔偿承包商损失的成本和利润。同时，请说明是否已提交基于出口信用保险（ECA）融资的备选报价。材料未明确是否已增加上述合同条款及ECA备选报价情况，需进一步确认。', 'medium', 0, NOW()),
(81, 0, '金融与专项资产管理部、法律事务部', 'R-B6', '保函转让条款风险及应对建议', '材料未明确预付款保函和履约保函中是否存在保函权益可转让条款，但法律意见书指出合同第1.1.111条允许业主转让合同项下全部或部分权益无需承包商同意，相关风险可能延伸至保函。建议进一步与业主沟通，争取在保函中明确禁止转让或要求转让需经承包商书面同意，同时明确保函具体失效日期，避免保函权益被转让后导致不可控的担保责任。投标阶段可参照法律意见书未落实意见一的风险措施，在标前澄清或合同谈判中增加限制条款。', 'medium', 0, NOW()),
(82, 0, '金融与专项资产管理部', 'R-I4', '保函金额需专项评估可用额度', '建议主张单位进一步落实保函开具要求，充分评估公司财务金融资源能否支撑项目保函金额。项目材料显示履约担保金额为41,300,000美元（约合人民币302,000,000元），但未明确公司现有可用保函额度及财务金融资源的具体状况，需进一步确认公司财务金融资源是否足以支撑该保函金额。严格履行保函开具程序，确保保函开具合法合规。鉴于招标文件通用合同条件第1.1.145条要求提供母公司担保，而投标方案拟以不提供母公司担保作为条件，需评估该策略对保函开具的合规性影响及替代方案，并与金融机构核实可用授信额度。', 'medium', 0, NOW()),
(83, 0, '法律事务部、海外部', 'R-A3,R-A7', '外部联营体及内部责任风险综合意见', '项目存在外部联营体合作模式不明、合作方资质缺失、担保责任不清晰及内部责任落实不足等核心风险。建议：1.补充说明外部联营体（ESEC 33.34%、HACS 33.33%、中建33.33%，ESEC牵头）的合作模式、决策机制和各方分工，核实ESEC和HACS的资质等级、财务状况及履约能力，确认是否已取得项目要求资质，后期是否更换履约主体；确保我方无需提供任何形式担保或代开保函。2.明确以股份公司名义承接项目的内部责任，中建中东作为牵头方应切实承担项目履约主体责任和牵头责任，通过项目管委会等机制落实重大事项决策，避免完全下沉至中建三局管理；如涉及系统内单位垫资，须提交审批决策文件。3.关注投标条件为不提供母公司担保，但业主招标文件Schedule 16要求提供，评估担保风险，并建立定期向股份公司汇报的机制。', 'medium', 0, NOW()),
(84, 0, '法律事务部', 'R-B3', '保函索赔条件增加违约证明要求', '项目招标文件Schedule 23为履约保函格式，但未明确业主兑付保函时需提交违约情形声明，存在业主不当索赔风险。建议在履约保函中增加条款：业主兑付保函前须提供承包商违约的书面证明，并抄送承包商。若材料中已有相关条款，需确认是否满足FIDIC第4.2条要求；若无，则应在投标阶段向业主提出修改。同时，母公司担保（Schedule 16）亦应增加类似条款。需在报价或谈判中落实此条件，以避免保函被滥用。', 'medium', 0, NOW()),
(85, 0, '法律事务部、海外部、科技与设计管理部', 'R-E1', '业主设计+固定总价下的设计责任归属与价格风险', '本项目由业主（Qiddiya Investment Company）负责设计，设计单位为BSBG，计价方式为固定总价。①法律角度：项目材料载明承包商承担“有限的主要工程设计责任”，与规则中“承包商仅对施工符合设计图纸和技术规范负责”存在差异。建议在合同中明确设计责任边界，业主对设计缺陷承担全部责任，承包商因业主设计缺陷导致的工期延误或成本增加有权获得工期延长和费用补偿。②商务角度：固定总价合同下，业主提供图纸和资料的准确性直接影响报价。建议充分评估设计深度对成本的影响，并争取在法规变化、业主要求变更等情形下启动价格调整机制。③技术角度：应提前制定技术报审计划，明确设计变更和优化建议的审批流程与时限，确保业主方及时响应，避免工期延误。材料未明确承包商“有限的主要工程设计责任”具体范围，需进一步确认。', 'medium', 0, NOW()),
(86, 0, '法律事务部、海外部', 'R-G2,R-G3,R-G4', '承包商停工权和解约权条款未明确，需争取约定并制定预案', '项目合同条件为业主自拟，适用沙特法律，材料未明确约定承包商的停工权和解约权。参照FIDIC红皮书/黄皮书第16条，承包商在业主付款违约等情形下应享有暂停工作及终止合同的权利。建议全面梳理招标文件中合同终止相关条款，确认是否明确承包商停工权和解约权，以及是否存在苛刻条件（如需业主书面同意、过长通知期、无补偿等）。如缺失或不利于承包商，应在投标阶段通过澄清函或谈判争取增加或优化相关条款，明确承包商在业主未按约定付款、工程师未按时签发证书等情形下的停工权和解约权。制定业主不同意情况下的应对措施，包括评估风险等级，在报价中增加风险费用，或设置其他合同保护机制（如提高预付款比例、缩短付款周期等）。', 'medium', 0, NOW()),
(87, 0, '海外部', 'R-A6', '外部联营体权益与管理不匹配，需明确管控措施', '外部联营体权益比例为ESEC 33.34%、HACS 33.33%、中建33.33%，且ESEC为牵头方，我方不担任牵头方。材料未明确我方拟采取的联营体管控措施，存在仅有权益不参与实质性管理的风险，可能无法在重大事项上保障充分的参与权和决策权。请补充说明我方拟采取的具体管控措施，包括但不限于：重大决策的投票权设计、关键岗位人员委派、信息报告机制、争议解决机制等，确保在联营体重大事项上具有充分的参与权和决策权。依据《境外项目评审管理办法》第4章及附件1。', 'medium', 0, NOW()),
(88, 0, '海外部', 'R-D3,R-D4,R-I2', '合同风险：罚款机制与地质责任需明确', '项目合同条款存在多处风险，需在谈判中明确相关责任分配。具体建议：1. 明确阶段性罚款退还机制，约定当总工期得以追回时已扣除的阶段罚款予以退还，并补充误期罚款日费率、上限及计价基数等具体数值。2. 明确误期罚款计价基数为合同总价，避免重复计算，并确认误期损害违约金为承包商唯一赔偿责任；若存在业主第三方协议下成本赔偿条款，应争取删除或限定上限。3. 依据FIDIC红皮书/黄皮书第4.12条，要求业主承担地下物理条件和不可知障碍物风险；需核实详细地质报告，并在投标报价中考虑地质勘察局限性；同时审查保险条款是否覆盖相关风险（第18条），确保风险敞口可控。', 'medium', 0, NOW()),
(89, 0, '海外部', 'R-E3,R-E5', '设计深度与专项审批风险综合意见', '设计阶段深度不足及专项审批周期不确定性构成主要风险。方案设计深度虽达100%，但后续技术设计、施工图阶段仍存在显著设计变更风险，需承包商在ECI阶段充分开展价值工程以锁定主要成本，并基于固定总价报价。应依据FIDIC黄皮书第5条明确设计责任边界，评估业主设计文件深度对报价的影响。同时，幕墙、内装、景观等专项工程需单独报审，材料未明确审批周期（含市政、消防等）及修改次数，建议提前制定报审计划，评估对工期和成本的影响，并在报价中预留相应时间和费用裕量。需进一步与业主确认审批流程、标准及修改次数。', 'medium', 0, NOW()),
(90, 0, '海外部', 'R-G6', '甲指分包终止费用承担风险需明确', '招标文件第5条提及指定分包商，但未明确因甲指分包或业主原因导致合同终止时，替换分包费用的承担主体。建议在投标前与业主澄清，要求将相关费用由业主承担的条款写入合同，并提前调研业主拟定的甲指分包工作内容和意向承包商，避免后续成本争议。材料中未明确具体费用承担安排，需进一步确认。', 'medium', 0, NOW()),
(91, 0, '海外部', 'R-H1', '商务部备案未完成，需在投标前补办', '本项目尚未完成商务部备案。根据《对外承包工程项目备案和立项管理办法》，境外工程承包项目应在投标前完成商务部备案。材料中未见备案信息，请确保在2025年4月24日投标截止前完成备案，否则可能影响投标合规性及后续合同签订。', 'medium', 0, NOW()),
(92, 0, '海外部', 'R-H2', '管理团队配置风险及明确要求', '请中建中东有限责任公司委派一名副总经理作为项目总指挥，亲自组织投标和后期实施。同时，请中建国际、中建三局提供拟选派的项目班子成员及其简历，并在ECI阶段即作为重点项目监管并提供必要支持，明确合作机制和费用承担原则，避免合作争议。目前项目仅明确内部联营体权益比例（33.4%:33.3%:33.3%），但未披露具体项目管理团队人选，存在配置不清晰风险。须尽快确定项目经理、技术负责人等关键岗位人员，并提交详细简历以供评审。', 'medium', 0, NOW()),
(93, 0, '海外部', 'R-H6', '分包招采计划与分供商管理方案缺失', '申请材料未明确潜在分包资源调研情况、各工作界面划分、分包招采计划以及分供商管理协调方案。该项目采用施工总承包模式，工作范围涵盖结构、钢结构、幕墙、机电、声光系统等多专业，分包管理复杂度高，缺乏上述信息将难以评估分包招采对成本和工期的影响。建议补充：1）主要分包资源及市场调研结果；2）工作包划分及界面管理方案；3）招采计划时间节点；4）分供商选择、评价及协调管理机制。', 'medium', 0, NOW()),
(94, 0, '海外部、科技与设计管理部', 'R-H7', '沙特奇迪亚艺术中心项目实施重难点及防范措施', '项目实施面临多重重难点：总建筑面积89,297平方米的飞船造型艺术场馆，由5个支腿支撑并建于山崖上，工期1643天，施工总承包涉及结构、钢结构、幕墙、机电、声光系统等多专业高危工种。需充分分析山崖基础施工、异形钢结构吊装、声学精装精度等风险，落实专项技术方案。组织系统内外结构工程、声学、机电等领域专家，对投标方案中的施工组织、技术路径、资源调配进行评审论证。中建中东公司总部应在投标阶段即作为重点项目监管，派驻技术组驻场，提供设计、施工、商务等多专业支持，确保投标方案符合实际条件并具备可实施性。', 'medium', 0, NOW()),
(95, 0, '海外部、科技与设计管理部', 'R-H8', '多标段兼投兼中与资源平衡', '本项目仅一个标段，且材料未明确允许兼投兼中。建议评估我方管理资源（人员、机械、资金）能否支撑该大型项目（合同额15亿美元，工期1643天）的实施。材料未提及同一区域其他在施项目，需进一步确认是否存在资源冲突风险。如存在其他项目，应说明资源统筹安排方案，避免多项目资源挤兑。', 'medium', 0, NOW()),
(96, 0, '海外部', 'R-H9', '管理团队资源冲突风险——信息缺失需补充', '拟派项目班子成员已在其他项目中任职，但当前材料未明确任何人员姓名、职务及在任的其他项目名称。根据《境外项目评审管理办法》第4章，需评估多项目间管理团队资源是否存在冲突。由于信息缺失，无法判断是否存在管理资源冲突风险。要求申请单位在评审补充材料中详细说明拟派项目班子成员（包括项目经理、技术负责人、商务经理等关键岗位）的姓名、职务及其当前在所有在建项目中的任职情况，并提交人员调配和统筹安排方案，明确核心成员在本项目中的投入时间占比，确保项目团队有充足精力投入本项目实施。请于3个工作日内补充上述信息，否则本次评审无法完成资源冲突风险评估。', 'medium', 0, NOW()),
(97, 0, '海外部', 'R-K1,R-K2', '政治风险与联营体资质合规综合评估', '项目执行期长达1643天，期间沙特“2030愿景”政策可能调整，且中沙双边关系存在不确定性，需提前应对；同时，我方及联营体合作方ESEC（33.34%）、HACS（33.33%）的沙特当地承包商资质需核实。建议：1. 充分评估政治风险对项目的影响，制定系统性应对措施，包括建立政策跟踪机制、保持政府沟通、在合同中加入政治不可抗力条款。2. 核实合作方是否已取得履约所需资质（如施工许可证、专业资质等），提供现有资质证书及有效期，确认其覆盖全部工作范围（如钢结构、剧院声光系统），若尚未取得需说明申请条件和预计完成时间。3. 若合作方拟更换履约主体（涉及中建中东、中建国际、中建三局），应论证更换的合规性并取得业主事先书面同意，避免因资质瑕疵导致合同无效。', 'medium', 0, NOW()),
(98, 0, '海外部', 'R-L3', '加快推进属地公司实体化经营，减少股份公司投标风险', '中建中东公司拟以股份公司名义参与沙特奇迪亚表演艺术中心总承包项目投标，内部联营体（中建中东33.4%、中建国际33.3%、中建三局33.3%）及外部联营体（ESEC 33.34%、HACS 33.33%、中建33.33%）均以股份公司为主体。理由为中东公司、中建国际不满足招标文件第4.6条关于类似项目经验和可持续发展奖项的资格要求。请申请单位切实承担管理主体责任，与中建国际、中建三局做好管理界面划分，落实重大事项管控机制，严控股份公司承接项目风险。同时，建议在今后投标活动中谨慎论证以股份公司名义承接项目的必要性，研判以中建中东或中建国际自身名义投标的可行性，更加关注在沙特阿拉伯地区的资质获取和业绩积累。具体可通过与当地承包商联营、分包等方式加快属地公司实体化经营进程，减少股份公司境外投标和履约活动的风险。材料未明确中东公司或中建国际在沙特地区的现有资质和业绩积累情况，需进一步确认。', 'medium', 0, NOW()),
(99, 0, '科技与设计管理部', 'R-H3', '技术方案评审：建议联动设计专家开展方案比选', '项目造型独特，设计灵感源自飞船，整体结构由5个支腿支撑，结构体系复杂。建议联动设计单位BSBG开展前期工作，确保工作成果的专业性。对关键技术方案如支腿结构、钢结构、幕墙安装、剧院声光系统等做好方案比选，从技术可行性、施工难度、成本可控性等维度综合评估，为商务测算提供支撑，规避后期重大变更风险。材料未明确技术方案的详细比选情况，需在后续阶段深化。', 'medium', 0, NOW()),
(100, 0, '科技与设计管理部', 'R-H4,R-H5', '当地资源与宗教节日风险综合评估', '项目对当地资源及宗教节日影响评估不足，存在成本超支和工期延误风险。建议：1. 深度摸排当地施工机械（大型吊装设备、混凝土泵车等）市场供应能力、租赁价格波动风险，以及地材（钢筋、水泥、砂石等）产能与质量保障情况，明确供应商名录、历史价格及供货周期；2. 劳动力高峰期用工约5500人，需提供当地实际工效对比数据，评估联营伙伴资源整合能力，避免工效偏差导致成本超支；3. 针对斋月（伊斯兰教历9月，日出至日落禁食）、开斋节、宰牲节等宗教节日，将斋月列为低效施工期，调整关键路径避免关键工序，预留赶工资源制定加班方案，并在合同中明确工期调整条款；4. 结合工期1643天，在施工组织设计中充分考虑每月有效工作日，避免关键路径受宗教节日影响。', 'medium', 0, NOW()),
(101, 0, '财务部', '', '业主资金来源为沙特公共投资基金PIF 及自有资金', '业主资金来源为沙特公共投资基金PIF及自有资金，请密切跟踪沙特公共投资基金PIF未来五年集中支付能力，持续关注业主及合作方资信风险（其中HACS母公司资产负债率达94%）。', 'medium', 1, NOW()),
(102, 0, '财务部', '', '关于内外部合作机制', '关于内外部合作机制，请明确项目管委会人员委派、权责界面划分、项目决策及争议解决机制，保障我方权益，避免内部合作争议，做好内部分包税务合规性安排，并在共同控制情形下按会计准则做好报表安排。', 'medium', 2, NOW()),
(103, 0, '财务部', '', '请明确以删除母公司担保为条件进行投标', '请明确以删除母公司担保为条件进行投标，并删除保函自动延期条款，增加保函减额和索赔相关单据条款。此外，原则上系统内反担保保函应优先使用中建财务公司保函，避免不必要保函费用。', 'medium', 3, NOW()),
(104, 0, '财务部', '', '请尽快补充项目成本策划、本外币现金流测算等资料', '请尽快补充项目成本策划、本外币现金流测算等资料，如涉及大额垫资，建议履行相应决策审批程序并明确资金来源，在标后及履约过程中，较原现金流测算出现较大负向偏差的，应重新履行“三重一大”决策程序。', 'medium', 4, NOW()),
(105, 0, '金融与专项资产管理部', '', '根据主张单位请示文件', '根据主张单位请示文件，本项目资金来源为业主自筹，建议密切关注业主自有资金落实情况和项目融资进展，防范项目回款风险。', 'medium', 1, NOW()),
(106, 0, '金融与专项资产管理部', '', '建议进一步在投标文件中明确我方不负责项目融资', '建议进一步在投标文件中明确我方不负责项目融资，不为项目融资提供任何形式的母公司担保或增信措施。', 'medium', 2, NOW()),
(107, 0, '法律事务部', '', '本项目管理模式之下', '本项目管理模式之下，总包商需要就包括暂列金部分在内的项目整体履约向业主承担全部责任，建议深入研究项目风险特点与管理要求，做好各管理界面协调，落实下游工程包合同“背靠背”风险传递与履约管控。', 'medium', 1, NOW()),
(108, 0, '法律事务部', '', '建议向业主澄清确认我方无需提供母公司担保', '建议向业主澄清确认我方无需提供母公司担保。', 'medium', 2, NOW()),
(109, 0, '法律事务部', '', '建议在预付款保函格式中增加随预付款的抵扣而逐步减', '建议在预付款保函格式中增加随预付款的抵扣而逐步减额的条款，同时在所有保函格式中均增加业主兑付保函时需提交违约情形声明相关条款。', 'medium', 3, NOW()),
(110, 0, '法律事务部', '', '建议做好内部分包的合规性安排', '建议做好内部分包的合规性安排，切实承担项目履约主体责任，落实重大事项管控机制，避免将项目完全下沉至内部分包单位管理，严控股份公司承接项目风险。', 'medium', 4, NOW()),
(111, 0, '海外部', '', '本项目尚未完成商务部备案', '本项目尚未完成商务部备案，请确保在正式投标前完成备案工作。', 'medium', 1, NOW()),
(112, 0, '海外部', '', '总包商需要对暂定金额（合计约11.11 亿美元）涉及的工', '总包商需要对暂定金额（合计约11.11亿美元）涉及的工作进行分包招采，开工后30天提交分包清单（每个工作包5家），业主决定中标分包或直接授标给总包商等。请说明对潜在分包资源的调研情况，做好各工作界面划分，提前制定分包招采计划、管理和协调方案，防范因分包招采导致的成本和工期风险。此外，鉴于业主负责设计且指定暂定金额，总包商无法控制工程造价和分包授标金额，建议删除“如招标后工作包金额超过暂定金额，总包商管理费调减”的约定。', 'medium', 2, NOW()),
(113, 0, '海外部', '', '本项目业主负责设计', '本项目业主负责设计，但要求承包商参与设计会议，就项目可建设性、建造方法以及材料选择等提出建议。考虑到本项目设计顾问公司多（至少10家），设计沟通协调难度和工作量大，请提前落实必要的设计资源和有经验的设计管理团队，制定设计风险防范措施。', 'medium', 3, NOW()),
(114, 0, '海外部', '', '合同同时约定了Section 8-整体移交的误期罚款（10 ', '合同同时约定了Section8-整体移交的误期罚款（10万里亚尔/日）和整体工程延误罚款（0.1%合同额/日），请澄清上述两类罚款是否存在重叠，并争取删除或降低整体工程延误罚款（0.1%合同额/日）以及各Section的误期罚款金额（Section5的日罚款高达548万里亚尔），以及当总工期追回情形下退还Section误期罚款，避免重复罚款。', 'medium', 4, NOW()),
(115, 0, '海外部', '', '本项目包括6 个单位工程', '本项目包括6个单位工程，其中“马术和马球俱乐部”仅完成方案设计（SchematicDesign），需承包商提供固定总价报价，请评估业主提供设计文件深度和准确性对投标报价的影响，防范项目价格风险，并与业主争取成本变动时的调价机制。', 'medium', 5, NOW()),
(116, 0, '海外部', '', '合同14.15 条索引的可支付预付款的材料设备清单附件', '合同14.15条索引的可支付预付款的材料设备清单附件在合同文件中并不存在，请确认本项目是否支付材料设备预付款。此外，本项目合同条件仍为此前评审的沙特萨勒曼国王知识区主工程承包项目合同条件，部分条款等与本项目合同协议中的约定不一致。请全面检索合同文件并向业主澄清确认。', 'medium', 6, NOW()),
(117, 0, '海外部', '', '招标文件明确列举了承包商应考虑的限制因素', '招标文件明确列举了承包商应考虑的限制因素，包括：项目区域存在VVIP居民、与政府机构和当地居民沟通协调、维护现有市政设施和道路、现场存在其他承包商、政府审批、承包商负责申请许可、洪水风险、地质条件风险等。请充分评估上述限制因素对项目工期和成本的影响，在投标方案和价格中落实风险防范措施。', 'medium', 7, NOW()),
(118, 0, '海外部', '', '本项目位于沙特历史遗迹区域', '本项目位于沙特历史遗迹区域，涉及保护历史遗迹、文化资产和具备历史意义的棕榈树等。请调研所需各类许可的办理要求，充分评估保护工作对项目成本、工期和施工组织的影响，提前制定应对措施。', 'medium', 8, NOW()),
(119, 0, '海外部', '', '请补充说明外部联合体合作模式、决策机制和各方分工', '请补充说明外部联合体合作模式、决策机制和各方分工，并确保我方无需向合作方提供任何形式的担保、无需代合作方开具保函。此外，请了解合作方ESEC、HACS的母公司是否均为其在本项目提供母公司担保，并进一步调查近年来沙特项目在授标后免除母公司担保的谈判空间，以及其他国际公司和中国公司的做法。', 'medium', 9, NOW()),
(120, 0, '海外部', '', '据评审资料', '据评审资料，中建股份沙特分公司选择中建一局作为内部合作单位，中建国际、中东公司与中建一局将共同组建项目管委会，请进一步说明各方在投标和履约阶段分工情况，并结合拟合作单位的类似项目经验和各项资源储备情况，评估其实施本项目的履约能力。如涉及系统内单位垫资，请提交其相应的审批决策文件。', 'medium', 10, NOW()),
(121, 0, '海外部', '', '本项目工期紧（973 天）、体量大（36 万平米）、施工', '本项目工期紧（973天）、体量大（36万平米）、施工区域分散，组织、协调、界面处理工作量大。请说明工期风险防范措施，充分分析项目实施面临的重难点，落实各项风险防范措施并做好投标方案的评审论证。', 'medium', 11, NOW()),
(122, 0, '海外部', '', '请提供拟选派的项目班子成员及其简历', '请提供拟选派的项目班子成员及其简历。鉴于本项目以股份公司名义投标，项目总负责人应由中建国际或中东公司派出。', 'medium', 12, NOW()),
(123, 0, '海外部', '', '请补充提供《项目投标情况说明与履约承诺函》和《项', '请补充提供《项目投标情况说明与履约承诺函》和《项目策划方案表》。请就上述会签意见进行澄清与回复。2024年3月4日', 'medium', 13, NOW()),
(124, 0, '财务部', 'F-R1,F-R3,F-R6', '财务部：现金流与垫资风险综合意见', '本项目财务风险集中于支付周期、垫资及业主违约风险，需在投标前明确。具体建议：①明确IPC支付周期：材料未约定业主收到IPC后的付款天数，直接影响现金流。建议争取缩短支付间隔，并基于约20亿美元暂估金额测算投标期资金峰值，评估自有资金压力；②量化垫资风险：需补充成本测算资料，明确高峰垫资金额及币种（预付款10%、质保金10%），按垫资审批制度完成审批并提前落实资金。联营体内部按权益比例（中建33.33%、ESEC33.34%、HAC33.33%）明确垫资及利息分摊机制；③防范业主付款违约：合同中应补充业主未按期付款的违约责任条款，防止过程垫资；④优化现金流：评估以保留金保函替代现金保留金的可行性及成本，做好全周期现金流测算，覆盖资金峰值及筹措安排。', 'medium', 0, NOW()),
(125, 0, '财务部', 'R-A1,R-A2,R-A4', '联营体权责、决策机制及合作方资信风险', '联营体权责划分、决策机制及合作方资信存在多重风险，需完善协议安排并补充财务调查。①内部联营体（中建国际、中建中东公司、中建一局）应在投标前签订标前协议，明确权责界面、投标费用分摊及项目委员会关键人员委派、重大事项决策程序与争议解决机制，重点规范资金支付、账务核算与税务分摊，并确认内部权益比例。②外部联营体（中建、ESEC、HAC权益分别为33.33%、33.34%、33.33%）权益高度均等，应优化决策机制，补充僵局解决条款（如特定事项多数决或引入第三方调解/仲裁），明确并表判断及财税权责，建立与贡献挂钩的业绩考核比例与分红流程。③补充获取ESEC和HAC的经审计财务报表或信用评级，重点核查资产负债率等关键财务指标，评估其财务稳健性与偿债能力，并在联营体协议中明确各方对项目财务的责任。', 'medium', 0, NOW()),
(126, 0, '财务部、法律事务部', 'R-B1,R-B2,R-B4,R-B5', '保函条款风险管控与优化建议', '履约保函、预付款保函及反担保保函均存在关键风险，需系统优化条款设计以控制敞口。具体建议：1. 依据FIDIC第4.2条，删除履约保函中“自动延期”“无义务调查索赔真实性”及“权益可转让第三方”等表述，明确失效日期，禁止自动延期（R-B1、R-B4）。2. 预付款保函应增设减额条款，明确金额随预付款逐月抵扣同比例减少，并设定自动触发机制（R-B2）。3. 针对7个单位工程、总工期973个日历天、总保额约2亿美元（签约总价10%），建议分标段开具保函，按关键里程碑（如马球俱乐部、各酒店主体结构）逐步释放金额，设置各标段上限及有效期，避免统一保函敞口（R-B4）。4. 反担保保函应优先使用中建财务公司，降低费用，要求合作方ESEC明确开立路径（R-B5）。', 'medium', 0, NOW()),
(127, 0, '财务部、法律事务部', 'R-C1,R-C2', '母公司担保风险与替代方案建议', '项目母公司担保存在资产负债率上升及担保额度占用风险，需严格评估并履行决策程序。具体建议：①根据《境外项目评审管理办法》第3章，若确需股份公司担保，应量化评估对资产负债率和担保额度的具体影响，并优先争取由子企业层级提供担保（需确认可行性）。②根据第4章，投标文件中应明确我方不负责项目融资，不为融资提供任何形式的母公司担保或增信措施。③如同意出具担保，须向业主确认担保提供主体和格式，明确因格式不符无法出具时的法律责任。④材料未明确招标文件中是否存在其他要求母公司担保的条款，需进一步核查。', 'medium', 0, NOW()),
(128, 0, '财务部、海外部', 'R-D2,R-G1', '合同违约责任条款风险与建议', '合同违约责任条款存在不一致：误期违约金上限（合同金额10%）符合FIDIC红皮书/黄皮书第8.7条标准，无需调整；但第R-G1条所指承包商最大违约责任比例显著高于国际工程惯例。建议：（1）在合同谈判中维持误期违约金日费率0.01%-0.02%/天及上限10%，并明确计价基数为合同总价；（2）争取将总违约责任上限从{当前比例}降低至{目标比例}；（3）明确该上限为承包商在合同项下的最终和唯一的金钱赔偿责任上限，同时关注例外情形是否导致该上限不适用。', 'medium', 0, NOW()),
(129, 0, '财务部', 'R-H10', '成本控制风险及报价准确性需关注', '根据《境外项目评审管理办法》第4章（评审范围：成本控制和报价风险管理），针对沙特瓦迪萨法尔项目（暂估投标金额20亿美元，暂列金11.11亿美元），材料未明确成本测算是否已完成，存在报价不准确风险；材料未明确材料设备采购依赖性，若供应链波动可能导致成本超支。建议：1）尽快完成成本测算，确保报价准确性；2）提前锁定分供商成本，签订意向协议；3）在投标报价中预留风险准备金。法律意见书显示，中标后将组建项目管理委员会负责成本控制，但具体策划需细化。请补充成本测算及供应链计划，降低报价风险。', 'medium', 0, NOW()),
(130, 0, '金融与专项资产管理部', 'F-R4,F-R5', '预付款与业主资金来源风险管控意见', '项目在预付款支付节点与业主资金落实方面存在风险，需加强财务风控。建议：1. 预付款为签约总价10%，分工作包支付（法律意见书第2节），应明确各工作包预付款到账后方可启动该工作包施工，避免垫资风险，符合《境外项目评审管理办法》第4章财务风控基本规定。2. 依据该办法第4章，业主（德拉伊耶门有限公司）资金来源于沙特公共投资基金（PIF），需提供资金已落实证明文件，并在合同中增加：承包商有权要求业主提供资金安排合理证明的条款，以及工程量减少时业主应支付承包商损失的成本和利润的条款。3. 说明是否提交基于出口信用保险（ECA）融资的备选报价，以防范沙特公共投资基金集中支付能力下降导致的回款风险。', 'medium', 0, NOW()),
(131, 0, '金融与专项资产管理部、法律事务部', 'R-B6', '保函转让条款风险及应对建议', '根据FIDIC红皮书/黄皮书第1.3条（转让）及第4.2条，保函权益转让应经承包商同意。本项目预付款保函和履约保函金额均为签约总价的10%。法律意见书已落实保函自动延期风险，但材料未明确保函权益是否可转让给第三方。为避免保函被转让后不可控风险，建议：1.进一步与业主沟通，争取删除保函转让相关条款；2.在保函中明确具体失效日期。若无法删除，需评估风险并增加控制措施，如要求转让须经我方书面同意。', 'medium', 0, NOW()),
(132, 0, '金融与专项资产管理部', 'R-I4', '保函金额评估：需确认可用额度是否覆盖10%履约保函', '根据《境外项目评审管理办法》附件1（保函金额评估），应评估保函金额是否超出可用额度。本项目履约保函为签约总价10%（约2亿美元），预付款保函也为签约总价10%。材料未明确公司当前可用保函额度，需进一步确认上述保函金额是否在公司及股份公司授信额度范围内。建议主张单位落实保函开具要求，充分评估公司财务金融资源能否支撑项目保函金额，严格履行保函开具程序，确保保函开具合法合规。若现有额度不足，需提前申请增额或调整担保结构，以避免保函开具受阻。', 'medium', 0, NOW()),
(133, 0, '法律事务部、海外部', 'R-A3,R-A7', '外部联营体与股份公司项目责任审查意见', '项目在外部联营体合作及股份公司名义承接方面存在关键合规与责任落实风险。具体建议：1. 根据《境外项目评审管理办法》第4章及附件1，补充说明外部联营体（中建股份33.33%、ESEC 33.34%、HAC 33.33%）的决策机制、争议解决及各方具体分工方案，并核实ESEC和HAC的资质等级、财务状况及履约能力，确认其是否已取得项目要求的资质等级。2. 明确中建国际作为股份公司名义承接项目的履约主体责任和牵头责任，落实重大事项管控机制，避免将项目完全下沉至中建一局管理；中建一局应作为主要实施方参与项目管委会，中建国际须对重要事项进行决策。3. 如涉及系统内单位垫资，需提交相应的审批决策文件，并依据管理办法评估合规性，确保责任不转移。', 'medium', 0, NOW()),
(134, 0, '法律事务部', 'R-B3', '保函索赔条件需增加违约情形声明条款', '根据FIDIC红皮书/黄皮书第4.2条（履约担保），保函索赔条件应要求业主兑付时提交违约情形声明。本项目履约保函为签约总价10%（来源：法律意见书第2节），但材料未明确保函格式是否包含该条款。建议在所有保函格式中均增加业主兑付保函时需提交违约情形声明的相关条款，以保障承包商合法权益。材料中提及保函自动延期风险已落实回复，但本意见针对索赔条件，需进一步确认是否已落实该条款。', 'medium', 0, NOW()),
(135, 0, '法律事务部、海外部、科技与设计管理部', 'R-E1', '明确业主设计责任并评估固定总价价格风险', '本项目由业主负责设计（基于FIDIC红皮书1999修改），计价方式为固定总价部分仅含“马术和马球俱乐部”单位工程（除部分FF&E等）及开办费，暂列金约41.68亿沙特里亚尔（约11.11亿美元）。
